// Norwegian KID / account checks (generated by scripts/bigplan/nocheck.py)
function hhMod10(s){if(!/^\d{2,25}$/.test(s))return false;let t=0;[...s].reverse().forEach((c,i)=>{let d=+c;if(i%2){d*=2;if(d>9)d-=9}t+=d});return t%10===0}
function hhMod11(b){const w=[2,3,4,5,6,7];let t=0;[...b].reverse().forEach((c,i)=>t+=c*w[i%6]);const r=11-t%11;return r===11?'0':r===10?'-':String(r)}
function hhKid(s){s=String(s).replace(/\s/g,'');if(hhMod10(s))return'MOD10';if(/^\d{1,24}[\d-]$/.test(s)&&s.length>=2&&hhMod11(s.slice(0,-1))===s.slice(-1))return'MOD11';return null}
function hhAccount(s){s=String(s).replace(/\D/g,'');if(s.length!==11||/^0+$/.test(s))return false;const w=[5,4,3,2,7,6,5,4,3,2];let t=0;for(let i=0;i<10;i++)t+=s[i]*w[i];let r=11-t%11;if(r===11)r=0;return r!==10&&r===+s[10]}
